package com.mushafi.app;
import android.app.Activity;import android.webkit.WebView;import android.media.*;import android.content.Context;import org.json.*;import java.io.*;import java.net.*;import java.util.concurrent.*;
final class AudioEngine implements AudioManager.OnAudioFocusChangeListener {
 private final Activity activity;private final WebView web;private final JSONObject catalog;private final AudioManager focus;private final ExecutorService downloads=Executors.newSingleThreadExecutor();
 private final ExecutorService verseDownloads=Executors.newSingleThreadExecutor();private volatile HttpURLConnection activeVerse;private volatile long generation;private boolean waitingForArchive;private String requestId="";private Runnable prepareTimeout;private final android.os.Handler clipHandler=new android.os.Handler(android.os.Looper.getMainLooper());private int clipStart=-1,clipEnd=-1;private boolean clipSeeking,clipWantsPlay,clipFinished;private int clipSeekAttempts;
 private final Runnable clipTick=new Runnable(){public void run(){MediaPlayer mp=player;if(mp==null||!prepared||clipEnd<0||clipSeeking||clipFinished)return;try{if(mp.isPlaying()&&mp.getCurrentPosition()>=clipEnd){finishClip(mp);return;}if(mp.isPlaying())clipHandler.postDelayed(this,25);}catch(Exception ignored){}}};
 private volatile HttpURLConnection activeDownload;private MediaPlayer player;private boolean prepared=false;private int reader=7;private String key="1:1";private volatile boolean cancelled=false,downloading=false,destroyed=false;
 AudioEngine(Activity a,WebView w)throws Exception{activity=a;web=w;focus=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=a.getAssets().open("audio-index.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}catalog=new JSONObject(out.toString("UTF-8"));}
 private boolean timed(int r){JSONObject spec=catalog.optJSONObject(String.valueOf(r));return spec!=null&&spec.has("segments");}
 private File file(int r,String k){if(timed(r))try{return TimedVerseSource.file(activity,r,k);}catch(Exception e){throw new IllegalArgumentException(e);}String suffix="";if(archive(r))try{suffix="-"+catalog.getJSONObject(String.valueOf(r)).getJSONObject("entries").getJSONArray(k).getString(5).substring(0,16);}catch(Exception e){throw new IllegalArgumentException("Invalid cached verse",e);}return new File(activity.getFilesDir(),(archive(r)?"audio/publisher-v1/":"audio/")+r+"/"+k.replace(':','_')+suffix+".mp3");}
 private String url(int r,String k)throws Exception{if(timed(r))return TimedVerseSource.url(catalog,r,k);String u=catalog.getJSONObject(String.valueOf(r)).getJSONObject("urls").getString(k);URL parsed=new URL(u);if(!parsed.getProtocol().equals("https")||!(parsed.getHost().equals("verses.quran.com")||parsed.getHost().equals("mirrors.quranicaudio.com")||parsed.getHost().equals("everyayah.com")))throw new IOException("Invalid audio source");return u;}
 private boolean archive(int r){JSONObject spec=catalog.optJSONObject(String.valueOf(r));return spec!=null&&spec.has("archive");}
 private boolean supports(int r,String k){if(k==null||!k.matches("[0-9]{1,3}:[0-9]{1,3}"))return false;JSONObject spec=catalog.optJSONObject(String.valueOf(r));return spec!=null&&spec.optBoolean("verseTimingVerified",true)&&((spec.optJSONObject("urls")!=null&&spec.optJSONObject("urls").has(k))||(spec.optJSONObject("entries")!=null&&spec.optJSONObject("entries").has(k))||(spec.optJSONObject("segments")!=null&&spec.optJSONObject("segments").has(k)));}
 boolean has(int r,String k){if(!supports(r,k))return false;File f=file(r,k);if(timed(r))try{return f.length()==TimedVerseSource.size(catalog,r,k);}catch(Exception e){return false;}if(!archive(r))return f.length()>100;try{return f.length()==catalog.getJSONObject(String.valueOf(r)).getJSONObject("entries").getJSONArray(k).getLong(2);}catch(Exception e){return false;}}

 int count(int r,int c,int verses){int n=0;for(int v=1;v<=verses;v++)if(has(r,c+":"+v))n++;return n;}
 private void send(JSONObject event){if(destroyed)return;final String js="window.onNativeAudio&&window.onNativeAudio("+event.toString()+")";activity.runOnUiThread(()->{if(!destroyed)web.evaluateJavascript(js,null);});}
 private void event(String status,String message){try{JSONObject j=new JSONObject();j.put("type","audio");j.put("requestId",requestId);j.put("status",status);j.put("reader",reader);j.put("key",key);j.put("message",message);send(j);}catch(Exception ignored){}}
 private void downloadEvent(String status,int r,int c,int done,int total){try{JSONObject j=new JSONObject();j.put("type","download");j.put("status",status);j.put("reader",r);j.put("chapter",c);j.put("done",done);j.put("total",total);send(j);}catch(Exception ignored){}}
 private void release(){if(prepareTimeout!=null){clipHandler.removeCallbacks(prepareTimeout);prepareTimeout=null;}clipHandler.removeCallbacks(clipTick);clipStart=clipEnd=-1;clipSeekAttempts=0;clipSeeking=clipWantsPlay=clipFinished=false;prepared=false;if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}}
 private void abortVerse(){HttpURLConnection c=activeVerse;if(c!=null)c.disconnect();activeVerse=null;waitingForArchive=false;}
 void play(int r,String k){play(r,k,"");}
 void play(int r,String k,String request){if(destroyed)return;requestId=request==null?"":request;final long ticket=++generation;abortVerse();release();reader=r;key=k;if(!supports(r,k)){event("error","تعذر فتح صوت الآية. حاول مرة أخرى.");return;}if(archive(r)){File target=file(r,k);if(has(r,k)){startMedia(r,k,target);return;}waitingForArchive=true;focus.abandonAudioFocus(this);event("loading","");verseDownloads.submit(()->{Exception failure=null;try{PublisherVerseArchive.download(catalog.getJSONObject(String.valueOf(r)),k,target,()->destroyed||generation!=ticket,c->{if(c!=null&&generation!=ticket)c.disconnect();else activeVerse=c;});}catch(Exception e){failure=e;}final Exception result=failure;activity.runOnUiThread(()->archiveReady(ticket,r,k,target,result));});return;}startMedia(r,k,null);}
 private void archiveReady(long ticket,int r,String k,File target,Exception failure){if(destroyed||generation!=ticket)return;waitingForArchive=false;if(failure!=null){event("error","تعذر تشغيل الآية. تحقق من اتصال الإنترنت ثم حاول مجددًا.");return;}startMedia(r,k,target);}
 private void startMedia(int r,String k,File local){try{if(timed(r)){int[] b=TimedVerseSource.bounds(catalog,r,k);clipStart=b[0];clipEnd=b[1];clipWantsPlay=true;}String source=local==null?url(r,k):local.getAbsolutePath();if(focus.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN_TRANSIENT)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){event("error","تعذر الحصول على إذن تشغيل الصوت الآن");return;}final MediaPlayer next=new MediaPlayer();player=next;next.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());next.setOnPreparedListener(mp->{if(player!=mp||destroyed)return;if(prepareTimeout!=null){clipHandler.removeCallbacks(prepareTimeout);prepareTimeout=null;}prepared=true;if(clipEnd>0){if(clipStart>=mp.getDuration()||clipEnd>mp.getDuration()+1000){release();focus.abandonAudioFocus(this);event("error","توقيت الآية لا يطابق التسجيل");return;}seekClip(mp);return;}mp.start();event("playing","");});next.setOnCompletionListener(mp->{if(player==mp){if(clipEnd>0)finishClip(mp);else event("ended","");}});next.setOnSeekCompleteListener(mp->{if(player!=mp||destroyed||!clipSeeking)return;clipSeeking=false;try{if(Math.abs(mp.getCurrentPosition()-clipStart)>250){if(clipSeekAttempts<3){seekClip(mp);return;}release();focus.abandonAudioFocus(this);event("error","تعذر ضبط بداية الآية؛ أعد المحاولة");return;}}catch(Exception e){release();focus.abandonAudioFocus(this);event("error","تعذر الانتقال إلى الآية");return;}if(clipWantsPlay)startClip(mp);});next.setOnErrorListener((mp,what,extra)->{if(player==mp){release();focus.abandonAudioFocus(this);event("error","تعذر تشغيل الآية. تحقق من اتصال الإنترنت ثم حاول مجددًا.");}return true;});if(local==null&&has(r,k))next.setDataSource(file(r,k).getAbsolutePath());else next.setDataSource(source);event("loading","");next.prepareAsync();prepareTimeout=()->{if(player==next&&!prepared){release();focus.abandonAudioFocus(this);event("error","تعذر تشغيل الآية. تحقق من اتصال الإنترنت ثم حاول مجددًا.");}};clipHandler.postDelayed(prepareTimeout,20000);}catch(Exception e){release();focus.abandonAudioFocus(this);event("error","تعذر فتح صوت الآية. حاول مرة أخرى.");}}
 private void startClip(MediaPlayer mp){if(player!=mp||destroyed||!clipWantsPlay)return;try{mp.start();clipHandler.removeCallbacks(clipTick);clipHandler.post(clipTick);event("playing","");}catch(Exception e){release();focus.abandonAudioFocus(this);event("error","تعذر تشغيل الآية");}}
 private void seekClip(MediaPlayer mp){clipSeekAttempts++;clipFinished=false;clipSeeking=true;try{if(android.os.Build.VERSION.SDK_INT>=26)mp.seekTo(clipStart,MediaPlayer.SEEK_CLOSEST);else mp.seekTo(clipStart);}catch(Exception e){release();focus.abandonAudioFocus(this);event("error","تعذر الانتقال إلى الآية");}}
 private void finishClip(MediaPlayer mp){if(player!=mp||clipFinished)return;clipFinished=true;clipWantsPlay=false;clipHandler.removeCallbacks(clipTick);try{if(mp.isPlaying())mp.pause();}catch(Exception ignored){}focus.abandonAudioFocus(this);event("ended","");}
 void pause(){clipWantsPlay=false;clipHandler.removeCallbacks(clipTick);boolean loading=waitingForArchive;++generation;abortVerse();if(player==null){if(loading){focus.abandonAudioFocus(this);event("paused","");}return;}if(prepared){try{if(player.isPlaying())player.pause();}catch(Exception ignored){}}else release();focus.abandonAudioFocus(this);event("paused","");}
 void resume(){if(player!=null&&prepared){if(focus.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN_TRANSIENT)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED){if(clipEnd>0){clipWantsPlay=true;if(clipSeeking)return;if(clipFinished){seekClip(player);return;}startClip(player);return;}player.start();event("playing","");}}else play(reader,key,requestId);}
 void stop(){++generation;abortVerse();release();focus.abandonAudioFocus(this);event("stopped","");}
 @Override public void onAudioFocusChange(int change){if(change<0)pause();}
 synchronized void download(final int r,final int chapter,final int total){if(destroyed)return;if(downloading){downloadEvent("busy",r,chapter,0,total);return;}if(total<1||total>286||chapter<1||chapter>114)return;if(!supports(r,chapter+":1")&&!timed(r))return;cancelled=false;downloading=true;downloads.submit(()->{int done=0;File temp=null;try{downloadEvent("loading",r,chapter,0,total);if(timed(r)){TimedVerseSource.download(catalog,r,chapter+":1",file(r,chapter+":1"),()->cancelled||destroyed,c->activeDownload=c);int available=0;for(int verse=1;verse<=total;verse++)if(supports(r,chapter+":"+verse))available++;downloadEvent("complete",r,chapter,available,available);return;}for(int v=1;v<=total;v++){if(cancelled||destroyed)break;String k=chapter+":"+v;File target=file(r,k);if(!has(r,k)&&archive(r)){PublisherVerseArchive.download(catalog.getJSONObject(String.valueOf(r)),k,target,()->cancelled||destroyed,c->activeDownload=c);}if(!has(r,k)){target.getParentFile().mkdirs();temp=new File(target.getAbsolutePath()+".part");HttpURLConnection conn=(HttpURLConnection)new URL(url(r,k)).openConnection();activeDownload=conn;conn.setConnectTimeout(20000);conn.setReadTimeout(30000);conn.setInstanceFollowRedirects(false);try{if(conn.getResponseCode()!=200)throw new IOException("HTTP "+conn.getResponseCode());String ct=conn.getContentType();if(ct==null||!(ct.startsWith("audio/")||ct.startsWith("application/octet-stream")))throw new IOException("Not audio");long expected=conn.getContentLength(),received=0;try(InputStream in=conn.getInputStream();FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(cancelled||destroyed)throw new InterruptedIOException();out.write(b,0,n);received+=n;}}if(received<100||(expected>=0&&expected!=received))throw new IOException("Incomplete audio");if(!temp.renameTo(target))throw new IOException("Cannot store audio");temp=null;}finally{conn.disconnect();if(activeDownload==conn)activeDownload=null;}}done++;downloadEvent("progress",r,chapter,done,total);}downloadEvent(cancelled?"cancelled":"complete",r,chapter,done,total);}catch(Exception e){downloadEvent(cancelled?"cancelled":"error",r,chapter,done,total);}finally{if(temp!=null)temp.delete();downloading=false;}});}
 void cancelDownload(){cancelled=true;HttpURLConnection conn=activeDownload;if(conn!=null)conn.disconnect();}
 synchronized void destroy(){if(destroyed)return;destroyed=true;++generation;abortVerse();verseDownloads.shutdownNow();cancelDownload();release();focus.abandonAudioFocus(this);downloads.shutdownNow();}
}
